# Intent
  arrangeManager: discovery, slot auto-allocation, placement, reswing.

# Helpers
  @fn mkAm(harness, opts)  @ 7-12
  @fn seedTracks(h, specs)  @ 18-40
      -- Seed two arbitrary tracks and a per-track item list. Returns the
      -- track tokens so each test can name them. The harness's default
      -- bindTake(take1) is unrelated — we manage these via setProjectTracks
      -- so am sees them in CountTracks/GetTrack order.
  @fn slotFor(am, trackIdx, id)  @ 42-44
  @fn slotAt(am, trackIdx, slotIdx)  @ 46-48

# Cases
  @case 'projectTracks lists every track in REAPER order with item count'  [harness]  @ 55-71
  @case 'trackSlots auto-allocates slot indices for live takes'  [harness]  @ 78-92
  @case 'tracksTakes assigns slotIdx to every grouped take'  [harness]  @ 96-114
  @case 'ensureSlots is idempotent — second read does not reallocate'  [harness]  @ 118-129
  @case 'hasPlacedTakes ignores parked takes, sees placed instances'  [harness]  @ 133-142
  @case 'ownerTrack resolves a parked take to its logical track, not scratch'  [harness]  @ 149-163
  @case 'renameSlot writes SetTakeName across every matching item'  [harness]  @ 170-183
  @case 'renameSlot reroots the family, each slot keeping its own ordinal'  [harness]  @ 187-204
  @case 'renameSlot with a changed ordinal renames that slot alone'  [harness]  @ 208-218
  @case 'two slots holding the root plain are namesakes, not a family'  [harness]  @ 222-234
  @case 'with the root held plain twice, a variant reroots neither'  [harness]  @ 238-250
  @case 'an unnamed slot has no family'  [harness]  @ 254-264
  @case 'the reroot reaches a parked family member'  [harness]  @ 268-277
  @case 'renameSlot renames a parked slot through its keeper'  [harness]  @ 281-288
  @case 'deleteSlot removes every matching item and prunes the dict entry'  [harness]  @ 292-310
  @case 'createAndDropMidi mints slot 0, creates a take, names it'  [harness]  @ 317-333
  @case 'createAndDropMidi allocates lowest-free index across calls'  [harness]  @ 337-348
  @case 'dropInstance pools to an existing slot'  [harness]  @ 352-363
  @case 'dropInstance overwrites a take already starting at the drop position'  [harness]  @ 367-384
  @case 'createAndDropMidi overwrites a take already starting at the create position'  [harness]  @ 388-403
  @case 'dropInstance returns nil for missing slot or missing track'  [harness]  @ 407-413
  @case 'duplicateTake clones a MIDI take into a pooled sibling'  [harness]  @ 417-432
  @case 'dropInstance and duplicateTake name the new take after the slot'  [harness]  @ 436-447
  @case 'duplicateTake returns nil for a missing track'  [harness]  @ 451-459
  @case 'dropInstance carries the sibling MIDI events into the new instance'  [harness]  @ 463-473
  @case 'duplicateTake carries the source MIDI events into the clone'  [harness]  @ 477-488
  @case 'startIsClear only collides on an exact start match (item ~= exceptItem)'  [harness]  @ 492-507
  @case 'createAndDropMidi returns nil when no track exists'  [harness]  @ 511-516
  @case 'keyForSlot maps 0..61 through util.toBase62'  [harness]  @ 523-532
  @case 'takesUsing scans each take swing map (ds) for the named swing'  [harness]  @ 539-557
  @case 'tempersInUse unions take/project temper names, minus the 12EDO floor'  [harness]  @ 560-574
  @case 'tracksTakes relayouts on read: an OPEN take grows to its source length'  [harness]  @ 584-593
  @case 'build relayout: OPEN takes fill to source; an earlier one capped at its gap (no overlap)'  [harness]  @ 596-607
  @case 'build relayout: an OPEN take whose item outruns its shrunk source is pulled back'  [harness]  @ 610-618
  @case 'a later take truncates an earlier one; deleting the later regrows it'  [harness]  @ 622-636
  @case 'resizeTake stores a numeric natural; ≥ source demotes back to util.OPEN'  [harness]  @ 640-656
  @case 'audio take longer than its source keeps its length across a move'  [harness]  @ 659-674
  @case 'trimmed audio take keeps its trim across a move (no balloon to source)'  [harness]  @ 677-689
  @case 'moveTake shifts start; refused on start-collision; returns ok flag'  [harness]  @ 693-704
  @case 'resizeTake writes natural; rendered is min(natural, source, gap)'  [harness]  @ 708-719
  @case 'trimHead walks the start edge in, holding the content and the end still'  [harness]  @ 723-739
  @case 'a head is refused before the origin, at the source end, or onto an occupied start'  [harness]  @ 742-753
  @case 'tailQN is the source past the rendered end, whatever shortened the take'  [harness]  @ 756-765
  @case 'head, rendered length and tail partition the source'  [harness]  @ 768-780
  @case 'a trimmed take is capped by the gap, and regrows to source-minus-head without one'  [harness]  @ 783-796
  @case 'trimming the head of a resized take keeps the end where the resize put it'  [harness]  @ 799-810
  @case 'splitTake cuts a take into two pooled halves that meet at the cut'  [harness]  @ 816-833
  @case 'the lower half inherits the natural, so the pair ends where the whole did'  [harness]  @ 836-848
  @case 'splitting a head-trimmed take leaves both halves on the source origin'  [harness]  @ 851-865
  @case 'a split is refused on either edge, off the take, and on audio'  [harness]  @ 868-881
  @case 'deleteTake removes the item, leaving the other take intact'  [harness]  @ 885-896
  @case 'deleteTake parks a slot\'s last instance; the slot survives, greyed'  [harness]  @ 902-918
  @case 'deleteTake of a non-last instance deletes outright (no park)'  [harness]  @ 922-937
  @case 're-dropping from a parked slot re-materialises off the keeper'  [harness]  @ 941-954
  @case 'deleteSlot forever-deletes: live instances and the parked keeper'  [harness]  @ 958-971
  @case 'deleteSlot forever-deletes the pool per-event metadata'  [harness]  @ 975-986
  @case 'mintParkedTake shows the new slot at once; isParkedTake flags scratch-hosted takes'  [harness]  @ 990-1005
  @case 'vary replaces the instance with one of a fresh variant slot'  [harness]  @ 1012-1034
  @case 'vary numbers from the family high-water mark; a variant of a variant joins the family'  [harness]  @ 1038-1049
  @case 'vary refuses on a slot with a single instance'  [harness]  @ 1053-1061
  @case 'stepVariant moves the placement onto the next slot of the family'  [harness]  @ 1068-1087
  @case 'stepVariant past the last of the family varies'  [harness]  @ 1091-1104
  @case 'stepVariant off the front of the family does nothing'  [harness]  @ 1108-1119
  @case 'stepping back off a variant parks it; stepping on again brings it live'  [harness]  @ 1123-1143
  @case 'a variant with two namesake bases steps forward but not back'  [harness]  @ 1147-1163
  @case 'findTake resolves a REAPER take handle back to its grid take-shape'  [harness]  @ 1170-1184
  @case 'initialCursor reads the selected item: its take track and start'  [harness]  @ 1188-1200
  @case 'initialCursor falls back to the edit cursor and selected track'  [harness]  @ 1204-1213
  @case 'initialCursor defaults to track 0 when nothing is selected'  [harness]  @ 1217-1225
  @case 'editCursorQN reads the REAPER edit cursor'  [harness]  @ 1232-1237
  @case 'setEditCursorQN moves the REAPER edit cursor'  [harness]  @ 1241-1246
  @case 'loopRangeQN returns the project loop range'  [harness]  @ 1250-1257
  @case 'loopRangeQN is nil when no loop is set'  [harness]  @ 1261-1265
  @case 'setLoopRangeQN writes the project loop range'  [harness]  @ 1269-1276
  @case 'loopTo brackets a span: loop range, repeat on, cursor at its start'  [harness]  @ 1280-1288
  @case 'loopTo leaves the cursor alone when the play head is inside the span'  [harness]  @ 1292-1301
  @case 'clearLoopRange removes the project loop range'  [harness]  @ 1305-1311
  @case 'playPositionQN is nil when the transport is stopped'  [harness]  @ 1315-1319
  @case 'playPositionQN returns the play head qn while playing'  [harness]  @ 1323-1328
  @case 'seekInstance takes the instance whose rendered span holds qn'  [harness]  @ 1335-1349
  @case 'seekInstance spans are half-open — the end belongs to the next'  [harness]  @ 1353-1362
  @case 'seekInstance from a gap travels forwards by default, backwards when asked'  [harness]  @ 1366-1378
  @case 'seekInstance falls back to the other direction when its own is empty'  [harness]  @ 1382-1392
  @case 'seekInstance ignores instances of other slots'  [harness]  @ 1396-1408
  @case 'seekInstance matches on the rendered span, not the source span'  [harness]  @ 1412-1424
  @case 'seekInstance is nil for a slot whose only take is parked'  [harness]  @ 1428-1438
  @case 'projectEndQN is 0 for a project with no items'  [harness]  @ 1442-1446
  @case 'projectEndQN reports the largest take end across all tracks'  [harness]  @ 1450-1459
  @case 'freeSpan is the gap to the next take, and unbounded past the last'  [harness]  @ 1466-1476
  @case 'duplicateBelow places a pooled clone at the append point'  [harness]  @ 1480-1496
  @case 'duplicateBelow refuses where a truncating neighbour leaves no room'  [harness]  @ 1500-1516
  @case 'duplicateBelow refuses where the gap is shorter than the natural length'  [harness]  @ 1520-1531
  @case 'duplicateBelow refuses on exact-start collision at the destination'  [harness]  @ 1535-1545
  @case 'duplicateBelow refuses on audio takes'  [harness]  @ 1549-1558
  @case 'newTakeBelow creates an empty MIDI take of the asked-for length at the append point'  [harness]  @ 1562-1583
  @case 'newTakeBelow parks the take for want of room'  [harness]  @ 1587-1599
  @case 'newTakeBelow measures the room against the length asked for'  [harness]  @ 1603-1614
  @case 'newTakeBelow refuses on audio'  [harness]  @ 1618-1626
  @case 'distinct pool guids on different tracks get distinct colourIdx'  [harness]  @ 1631-1644
  @case 'pooled instances on different tracks share one colourIdx'  [harness]  @ 1648-1658
  @case 'createAndDropMidi stamps I_CUSTOMCOLOR on the new take'  [harness]  @ 1662-1670
  @case 'placement does not overwrite a pre-existing take colour (preserve override)'  [harness]  @ 1674-1686
  @case 'a recycled take handle reports the new item\'s pool, not the dead take\'s'  [harness]  @ 1691-1714

